s = input().strip()
stack = []
pairs = {')': '(', ']': '[', '}': '{'}
valid = True
for ch in s:
    if ch in '([{':
        stack.append(ch)
    elif not stack or stack.pop() != pairs[ch]:
        valid = False
        break
print('YES' if valid and not stack else 'NO')

