#include <iostream>
#include <stack>
#include <string>
using namespace std;
int main() { string s; cin >> s; stack<char> st; bool ok = true; for (char c : s) { if (c == '(' || c == '[' || c == '{') st.push(c); else { char expected = c == ')' ? '(' : c == ']' ? '[' : '{'; if (st.empty() || st.top() != expected) { ok = false; break; } st.pop(); } } cout << (ok && st.empty() ? "YES" : "NO") << '\n'; }
